                    {"ticker":"MMLP","nama":"Mega Manunggal Property", "fase":"Lagging",   "rs":94, "mom":95},
                    # Improving: rs<100 DAN mom>100
                    {"ticker":"DMAS","nama":"Puradelta Lestari",       "fase":"Improving", "rs":98, "mom":101},
