        def _render_sh_table_v2(rows, is_naik):
            if not rows:
                return
            rows_sorted = sorted(rows, key=lambda x: abs(x["_pct"]), reverse=True)
            acc        = _acc_up if is_naik else _acc_dn
            delta_cls  = "up"  if is_naik else "dn"
